@Override public void onError(WebSocket webSocket,Throwable t){
  logger.debug("{}: Throwable received from websocket",LOG_PREFIX,t);
  if (alive.get()) {
    try {
      serverThrowables.add(t);
      closeForwarder();
    } catch (RuntimeException e) {
      logger.error("Exception in onError handling", e);
    }
  }
}
